            require(page.count('${genomicsemVersion(t)}')==1 and page.count('function renderContent(){')==1,'Changed inherited renderer');helper=("function prsiceVersion(t){if(t.tool_id!=='prsice'||!t.source_role_qualification)return genomicsemVersion(t);const q=t.source_role_qualification;return '<br><span class=\"prsice-version\" style=\"overflow-wrap:anywhere\">Role: '+esc(q.role_kind)+'; Reported edition: '+esc(q.reported_version)+'; '+esc(q.historical_analysis_status)+'; '+esc(q.remaining_scope)+'</span>';}\n");page=page.replace('${genomicsemVersion(t)}','${prsiceVersion(t)}',1).replace('function renderContent(){',helper+'function renderContent(){',1)
